/**
 * The REAL tree's daemon registry, for a test that boots the daemon of this commit (not a fixture workspace's):
 * `packages/core/kernel/src/generated/plugins.ts`, git-ignored and regenerated by install, build, test and typecheck. It
 * is exactly what `packages/core/kernel/host/fyd.ts` imports, so a daemon started over it says the hashes `fyd` says.
 *
 * It lives here, beside the two-release rig, because a package's tests reach another package only through its contract
 * (`context-imports`) and this registry is the one place the daemon's halves meet.
 */
import type { DaemonRegistry } from './releases.ts';

export async function realDaemonRegistry(): Promise<DaemonRegistry> {
  return (await import('../../../packages/core/kernel/src/generated/plugins.ts')) as unknown as DaemonRegistry;
}
